// Identifier les prospects à relancer selon leur statut et délai
const aujourd_hui = new Date();
const DELAI_RELANCE_1_JOURS = 7;
const DELAI_RELANCE_2_JOURS = 14;

const toRelancer = [];

for (const item of $input.all()) {
  const p = item.json;
  const statut = p.STATUT || '';
  const email = p.EMAIL || '';
  const dateAction = p.DATE_DERNIER_ENVOI ? new Date(p.DATE_DERNIER_ENVOI) : null;

  if (!email.includes('@') || !dateAction) continue;

  const joursEcoules = Math.floor((aujourd_hui - dateAction) / (1000 * 60 * 60 * 24));

  let typeRelance = null;
  if (statut === 'contacté' && joursEcoules >= DELAI_RELANCE_1_JOURS) {
    typeRelance = 'relance_1';
  } else if (statut === 'relance_1' && joursEcoules >= DELAI_RELANCE_2_JOURS) {
    typeRelance = 'relance_2';
  }

  if (typeRelance) {
    toRelancer.push({ json: { ...p, typeRelance, joursEcoules } });
  }
}

console.log(`${toRelancer.length} prospects à relancer aujourd'hui`);
return toRelancer.length > 0 ? toRelancer : [{ json: { _empty: true } }];

// Construire le prompt Claude selon le type de relance
const p = $input.first().json;
const typeRelance = p.typeRelance;

// Construire URLs preview + commander
const secteurIds = {
  'Restauration': 'restauration', 'Beauté': 'beaute', 'Automobile': 'automobile',
  'Auto-école': 'auto_ecole', 'Santé': 'sante', 'Artisanat': 'artisanat',
  'Hôtellerie': 'hotellerie', 'Services': 'services'
};
const secteurId = secteurIds[p.SECTEUR] || 'services';
const pvParams = `nom=${encodeURIComponent(p.ENTREPRISE||'')}&secteur=${secteurId}&ville=${encodeURIComponent(p.VILLE||'')}&note=${p.NOTE_GOOGLE||'4.2'}&nb_avis=${p.NB_AVIS||0}&sans_rep=${p.AVIS_SANS_REPONSE||0}&prenom=${encodeURIComponent(p.PRENOM||'')}`;
const urlPreviewSite = `https://replyshield.io/preview.html?${pvParams}`;
const urlCommander   = `https://replyshield.io/commander.html?nom=${encodeURIComponent(p.ENTREPRISE||'')}&secteur=${secteurId}&ville=${encodeURIComponent(p.VILLE||'')}&prenom=${encodeURIComponent(p.PRENOM||'')}&offre=essentiel`;

let promptObjet, promptCorps;

if (typeRelance === 'relance_1') {
  promptObjet = `Génère 1 objet de relance douce (max 55 caractères) pour ${p.PRENOM || 'le dirigeant'} de ${p.ENTREPRISE}. C'est la première relance J+7. Ton décontracté, inclus le prénom si possible. Réponds uniquement avec l'objet.`;

  promptCorps = `Rédige une relance douce (J+7) pour ${p.PRENOM || 'le dirigeant'} de ${p.ENTREPRISE} (${p.SECTEUR}) à ${p.VILLE}.

Contexte : Tu lui as envoyé un email il y a 7 jours à propos de ReplyShield (avis Google) et d'un aperçu gratuit de site web. Il n'a pas répondu.

Ses chiffres : ${p.AVIS_SANS_REPONSE} avis sans réponse sur ${p.NB_AVIS} total, note ${p.NOTE_GOOGLE}/5.

Liens à utiliser :
- Aperçu de son site (toujours disponible) : ${urlPreviewSite}
- Commander le vrai site : ${urlCommander}

Contraintes :
- 90 mots maximum
- Ton : léger, humain, pas de pression
- Mentionne que l'aperçu de son site l'attend encore : ${urlPreviewSite}
- CTA principal : commander le site → ${urlCommander}
- Ne répète pas le premier email mot pour mot
- Signe avec 'L'équipe ReplyShield'

Réponds uniquement avec le corps, sans objet.`;

} else {
  promptObjet = `Génère 1 objet de relance finale (max 50 caractères) pour ${p.PRENOM || 'le dirigeant'} de ${p.ENTREPRISE}. C'est le dernier message. Légèrement urgent, pas agressif. Réponds uniquement avec l'objet.`;

  promptCorps = `Rédige la relance finale (J+14) pour ${p.PRENOM || 'le dirigeant'} de ${p.ENTREPRISE} (${p.SECTEUR}).

C'est le dernier email de la séquence. Crée une légère urgence sans être agressif. Mentionne explicitement que c'est le dernier message.

Ses chiffres : ${p.AVIS_SANS_REPONSE} avis sans réponse, note ${p.NOTE_GOOGLE}/5.
Lien essai : https://replyshield.io/essai-gratuit (14 jours gratuits, sans carte)
Lien désinscription : https://replyshield.io/desinscription?id=${p.ID}

Contraintes :
- 70 mots maximum
- Inclure le lien de désinscription en fin de message
- Signe avec 'L'équipe ReplyShield'

Réponds uniquement avec le corps, sans objet.`;
}

return [{ json: { ...p, promptObjet, promptCorps } }];

