const prospect = $('Préparer prompt selon type de relance').first().json;
const objet    = $('Claude — Objet relance').first().json.content?.[0]?.text?.trim() || 'Juste un rappel...';
const corps    = $('Claude — Corps relance').first().json.content?.[0]?.text?.trim() || '';
const tag      = prospect.typeRelance === 'relance_1' ? 'relance-1' : 'relance-finale';

return [{ json: { ...prospect, relance_objet: objet, relance_corps: corps, tag } }];

